template:
use std::thread;

fn sum_threads() -> i32 {
    let mut handles = Vec::new();
    for i in 1..=3 {
        handles.push(thread::spawn(move || i * 10));
    }
    let mut sum = 0;
    for handle in handles {
        sum += handle.⟦slot1⟧().⟦slot2⟧();
    }
    sum
}

fn main() {
    println!("{}", sum_threads());
}
